import type { Faq } from "@/data/products";
/**
 * Lending partners. Keep this list aligned with live empanelments; the
 * README explains how to add or remove a lender. Descriptions use public
 * information about each institution and do not state rates.
 */
export type LenderType = "Public sector bank" | "Private bank" | "Housing finance company" | "NBFC" | "Small finance bank";

export type Lender = {
  slug: string;
  name: string;
  shortName: string;
  type: LenderType;
  products: string[];
  strengths: string[];
  summary: string;
  bestFor: string;
  /**
   * Our desk's read on where this lender fits, written per lender rather than
   * generated from a template. These pages exist to help someone choose, so
   * anything true of every lender of this type belongs in shared copy, not
   * here. Nothing in these fields states a rate, a fee or a policy rule: those
   * change without notice and belong to the lender, not to us.
   */
  profile: string[];
  /** Honest caveats. A page that only praises a lender is not advice. */
  watchOuts: string[];
  faqs: Faq[];
  website: string;
  updatedAt: string;
};

export const lenders: Lender[] = [
  { slug: "hdfc-bank", name: "HDFC Bank", shortName: "HDFC Bank", type: "Private bank", products: ["personal-loan", "home-loan", "business-loan", "loan-against-property", "car-loan", "used-car-loan", "education-loan", "gold-loan", "professional-loan", "working-capital-loan", "home-loan-balance-transfer"], strengths: ["Pre-approved offers for salary account holders", "Fast personal and car loan turnaround", "Large home loan franchise after the HDFC merger"], summary: "India's largest private sector bank by assets, with a broad retail and SME lending franchise and one of the country's largest home loan books.", bestFor: "Salaried professionals seeking competitive personal, home and car loan pricing.", profile: ["HDFC Bank sits at the centre of most salaried files we place. Its appetite is broadest where the borrower has a clean repayment record, a stable employer and a salary account it can see, because that combination lets the bank price on observed behaviour instead of on documents alone. If you bank here already, tell us: a pre-approved line often exists that never gets surfaced unless someone asks for it.", "Since the merger with HDFC Ltd the same institution now holds one of the largest home loan books in the country alongside its retail franchise, so a single file can be assessed for a home loan, a top-up and a personal loan without moving between lenders. That matters most for borrowers who want their entire relationship in one place rather than the sharpest possible rate on each product."], watchOuts: ["Pricing rewards existing relationships, so a first-time customer with the same profile may be quoted less keenly than someone with a salary account here.", "Documentation standards are strict on income proof; informal or variable income is usually better placed with a housing finance company or an NBFC."], faqs: [{ question: "Do I need an HDFC Bank salary account to get a good rate?", answer: "No, but it helps. The bank prices partly on what it can observe directly, so an existing salary or savings relationship often produces a better offer than the same profile arriving cold. We check both routes before we submit anything." }, { question: "Can HDFC Bank handle my home loan and personal loan together?", answer: "Yes. After the merger with HDFC Ltd the home loan and retail books sit in the same institution, so one credit view can cover both. Whether that is the cheapest combination is a separate question, and it is the one we answer for you." }, { question: "How does LoansPartner apply on my behalf?", answer: "We pre-screen your profile against the bank's published eligibility and against the rest of our panel first. Only when the fit is clear do we submit, which keeps needless bureau enquiries off your report." }], website: "https://www.hdfcbank.com", updatedAt: "2026-09-01" },
  { slug: "icici-bank", name: "ICICI Bank", shortName: "ICICI Bank", type: "Private bank", products: ["personal-loan", "home-loan", "business-loan", "loan-against-property", "car-loan", "education-loan", "gold-loan", "working-capital-loan", "home-loan-balance-transfer"], strengths: ["Digital sanction for existing customers", "Competitive home loan rates for approved projects", "Strong MSME and working capital programmes"], summary: "A leading private bank with a full suite of retail and business lending products and an emphasis on digital processing.", bestFor: "Home buyers in approved projects and businesses needing working capital lines.", profile: ["ICICI Bank is usually our first look for a home purchase in a project the bank has already approved. Where the builder and tower are pre-cleared, the legal and technical work is largely done, and a file that would otherwise take weeks can move considerably faster. Ask us to check the approved-project list before you commit to a booking date.", "On the business side the bank runs structured working capital and MSME programmes rather than case-by-case lending, which suits a company with audited accounts and consistent banking. Digital sanction is genuinely quick for existing customers, though the speed comes from data the bank already holds, so a new-to-bank applicant should expect an ordinary timeline."], watchOuts: ["The advantage largely disappears outside approved projects, where a resale or an older building can face a slower legal and technical review.", "Business programmes expect clean, audited financials; a firm with informal books is usually a poor fit here."], faqs: [{ question: "What is an approved project and why does it matter?", answer: "It is a development the bank has already vetted for title and construction quality. Buying in one removes most of the legal and technical review from your file, which is the single biggest cause of home loan delays. We check the list before you fix a booking date." }, { question: "Is the digital sanction real or just an in-principle number?", answer: "For existing customers it is a genuine credit decision built on data the bank already holds. For a new applicant it is closer to an indicative offer that still needs documents. We tell you which one you are looking at." }, { question: "Can I get a working capital line as a small business?", answer: "Yes, if your accounts are audited and your banking is consistent. The programmes here are structured rather than discretionary, so the fit is usually clear before we apply." }], website: "https://www.icicibank.com", updatedAt: "2026-09-01" },
  { slug: "axis-bank", name: "Axis Bank", shortName: "Axis Bank", type: "Private bank", products: ["personal-loan", "home-loan", "business-loan", "loan-against-property", "car-loan", "education-loan", "gold-loan", "working-capital-loan", "home-loan-balance-transfer"], strengths: ["Competitive personal loan pricing for corporate salary accounts", "Flexible home loan variants", "Active business loan programmes"], summary: "One of India's largest private banks, active across personal, home, vehicle and business lending.", bestFor: "Corporate salaried borrowers and SMEs with strong banking.", profile: ["Axis Bank is at its most competitive on personal loans for people employed by companies on its approved corporate list. That list, not your salary figure, is often what separates a sharp quote from an ordinary one, so it is the first thing we check. If your employer is on it, this is frequently the strongest unsecured option on our panel.", "The home loan range includes several variants that behave differently over the life of the loan, including structures aimed at borrowers who expect income to rise. These are worth understanding before you sign, because the cheapest opening rate and the cheapest total cost are not always the same product."], watchOuts: ["Personal loan pricing is noticeably employer-sensitive, so a strong applicant at an unlisted company may do better elsewhere.", "The choice between home loan variants materially changes what you pay overall; the headline rate alone will mislead you here."], faqs: [{ question: "How do I know if my employer is on the approved list?", answer: "Ask us. The list is not public and it changes, so guessing wastes an application. We check it against your employer before we submit anything, and if you are not on it we move to a lender where that does not matter." }, { question: "Which Axis home loan variant should I choose?", answer: "It depends on how you expect your income and your prepayment ability to change. We model the total cost of each option against your actual plans rather than comparing opening rates, which is where most borrowers go wrong." }, { question: "Is a corporate salary account required?", answer: "No. It is one of several inputs into pricing, not a gate. A strong credit history and stable employment can carry a file on their own." }], website: "https://www.axisbank.com", updatedAt: "2026-09-01" },
  { slug: "kotak-mahindra-bank", name: "Kotak Mahindra Bank", shortName: "Kotak", type: "Private bank", products: ["personal-loan", "home-loan", "business-loan", "loan-against-property", "car-loan", "working-capital-loan", "home-loan-balance-transfer"], strengths: ["Sharp home loan pricing for strong profiles", "Loan against property programmes for self-employed", "Established car finance business"], summary: "A private bank known for its home loan pricing, loan against property programmes and vehicle finance arm.", bestFor: "Salaried home buyers and self-employed borrowers with property.", profile: ["Kotak tends to price home loans keenly for borrowers whose profile is unambiguous: clean bureau record, documented income, straightforward property. Where a file is clean, this is often among the sharper quotes on the panel. Where it is not, the bank is generally less flexible than a housing finance company, and we will say so rather than waste your time.", "Its loan against property programmes are the more interesting part of the franchise for self-employed borrowers. A property-backed file here can support a larger amount than an unsecured route would, and the assessment gives real weight to the asset rather than resting entirely on declared income."], watchOuts: ["Flexibility on non-standard income or unusual property is limited compared with a specialist housing finance company.", "A loan against property means the asset is at risk, so the lower rate against an unsecured loan is not free."], faqs: [{ question: "Is Kotak good for a self-employed borrower?", answer: "For a loan against property, often yes, because the asset carries part of the assessment. For an unsecured loan with informal income, a specialist NBFC is usually the better route and we will point you there." }, { question: "What makes a file clean enough for the sharpest pricing?", answer: "A strong bureau score with no recent defaults, income you can document properly, and a property with clear title in a standard location. We tell you which of these you are missing before we apply." }, { question: "How much can I raise against my property?", answer: "It depends on the valuation and on your ability to service the loan, both of which the lender assesses. We give you a realistic range up front rather than an optimistic one." }], website: "https://www.kotak.com", updatedAt: "2026-09-01" },
  { slug: "state-bank-of-india", name: "State Bank of India", shortName: "SBI", type: "Public sector bank", products: ["personal-loan", "home-loan", "car-loan", "education-loan", "gold-loan", "business-loan", "working-capital-loan", "home-loan-balance-transfer"], strengths: ["India's largest home loan lender", "Concessional rates for government and defence employees", "Low processing fees on education and gold loans"], summary: "The country's largest bank and largest home loan lender, with a nationwide branch network and strong public sector employee programmes.", bestFor: "Government employees, home buyers seeking the lowest published rates, and education loan applicants.", profile: ["State Bank of India is the default comparison point for home loans, and for good reason: the published rates are hard to beat and concessional schemes exist for government, defence and public sector employees that no private bank matches. If you work in any of those, this should be on your shortlist before anything else.", "The trade-off is process. A branch-led file moves at the pace of the branch, and documentation is checked thoroughly. For an education loan or a home loan where the rate matters more than the timeline, that is a fair exchange. Where you have a booking deadline in weeks, we will tell you honestly whether it can be met."], watchOuts: ["Turnaround is generally slower than at a private bank or a housing finance company, so build the timeline into your booking plan.", "Service quality varies by branch more than it does at a centralised lender, and the branch handling your file is not always yours to choose."], faqs: [{ question: "Do government employees really get better terms?", answer: "Concessional schemes for government, defence and public sector staff are a long-standing part of the bank's offering. Whether one applies to you depends on your employer and the current scheme, which we confirm before applying." }, { question: "Is an SBI home loan worth the slower process?", answer: "If the rate matters more than the timeline, frequently yes. If you have a booking deadline in weeks, we will tell you plainly whether it is realistic and offer a faster alternative if it is not." }, { question: "Why are education loans often placed here?", answer: "Public sector banks have long-established education loan schemes and are generally the most economical route, particularly for study in India. We compare the total cost including any subsidy you qualify for." }], website: "https://sbi.co.in", updatedAt: "2026-09-01" },
  { slug: "bank-of-baroda", name: "Bank of Baroda", shortName: "BoB", type: "Public sector bank", products: ["personal-loan", "home-loan", "car-loan", "education-loan", "gold-loan", "business-loan", "loan-against-property"], strengths: ["Competitive home and car loan rates", "Strong MSME lending", "Wide branch presence in western and northern India"], summary: "A large public sector bank with competitive retail rates and a deep MSME franchise.", bestFor: "Salaried home and car buyers and MSMEs seeking bank pricing.", profile: ["Bank of Baroda is a practical alternative when you want public sector pricing without defaulting automatically to the largest lender. Retail rates on home and car loans are competitive, and the MSME franchise is deeper than most borrowers expect, particularly across western and northern India where the branch network is densest.", "For a salaried borrower with documented income and a standard property, the outcome here is often close to the best public sector quote available, with a process that can be marginally more responsive at a well-run branch. We place files here when the profile is straightforward and the borrower values rate over speed."], watchOuts: ["As with any branch-led public sector lender, the experience depends heavily on the branch handling your file.", "Appetite for non-standard property or informal income is limited; those files belong with a housing finance company."], faqs: [{ question: "How does this compare with the largest public sector bank?", answer: "Pricing is usually in the same territory, so the decision often comes down to branch responsiveness and which scheme you qualify for. We quote both rather than assuming the biggest name wins." }, { question: "Is it a good option for an MSME?", answer: "The MSME franchise is genuinely deep, particularly in western and northern India. A firm with clean books and consistent banking is a reasonable fit, and we assess that before applying." }, { question: "Can I transfer an existing home loan here?", answer: "A balance transfer is possible where the rate gap justifies the switching cost. We calculate whether it actually saves you money, including fees, before recommending it." }], website: "https://www.bankofbaroda.in", updatedAt: "2026-09-01" },
  { slug: "punjab-national-bank", name: "Punjab National Bank", shortName: "PNB", type: "Public sector bank", products: ["personal-loan", "home-loan", "car-loan", "education-loan", "gold-loan", "business-loan"], strengths: ["Strong presence in northern India", "Concessional schemes for government employees", "Competitive home loan rates"], summary: "One of India's largest public sector banks, particularly strong across North India.", bestFor: "Government and PSU employees in North India.", profile: ["Punjab National Bank is strongest where its network is strongest, across northern India, and for borrowers employed by government and public sector organisations. Concessional schemes for those employees are a real advantage and are frequently the reason a file lands here rather than at a private bank.", "For a home loan on a standard property with documented income, the pricing is competitive with any public sector lender. We place files here when the borrower is in the North, values rate over turnaround, and has the documentation to support a thorough branch review."], watchOuts: ["Presence and service depth taper outside northern India, so a borrower elsewhere may be better served by another public sector bank.", "Expect a documentation-heavy process; the timeline is not comparable with a digital-first lender."], faqs: [{ question: "Do I need to be in North India to apply?", answer: "No, but the branch network and service depth are strongest there. Elsewhere we usually find a better-matched public sector option, and we will say which." }, { question: "What concessions exist for government employees?", answer: "Public sector banks maintain long-running schemes for government and PSU staff. Which one applies depends on your employer and the current terms, so we confirm it rather than assume." }, { question: "How long does a home loan take here?", answer: "Longer than a private bank or a housing finance company, because the review is thorough and branch-led. If you have a fixed booking deadline, tell us early so we can plan around it." }], website: "https://www.pnbindia.in", updatedAt: "2026-09-01" },
  { slug: "union-bank-of-india", name: "Union Bank of India", shortName: "Union Bank", type: "Public sector bank", products: ["home-loan", "personal-loan", "car-loan", "education-loan", "business-loan", "gold-loan"], strengths: ["Competitive home loan rates", "Strong MSME schemes", "Wide branch network"], summary: "A large public sector bank with a strong home loan and MSME focus.", bestFor: "Home buyers seeking public sector bank pricing.", profile: ["Union Bank of India is a straightforward public sector choice for a home loan on a standard property, with pricing that sits alongside its peers and a wide branch network that makes it accessible outside the metros. Its MSME schemes are worth a look for a small business with clean accounts.", "We tend to place files here when a borrower wants public sector pricing, has documented income, and is served by a nearby branch. It rarely wins on speed, and it is not the answer for a complex or informal-income file."], watchOuts: ["The process is branch-led and paperwork-heavy, so the timeline needs planning.", "Little flexibility on unusual property or undocumented income."], faqs: [{ question: "Is this a good first choice for a home loan?", answer: "It is a reasonable one for a standard property and documented income. Whether it beats the other public sector options for you depends on the scheme you qualify for, which we check." }, { question: "Does it lend to small businesses?", answer: "Yes, through structured MSME schemes. A firm with audited accounts and steady banking is the right fit; informal books are not." }, { question: "What if my nearest branch is far away?", answer: "That matters more here than at a digital lender, because the file is handled locally. We factor branch access into the recommendation rather than ignoring it." }], website: "https://www.unionbankofindia.co.in", updatedAt: "2026-09-01" },
  { slug: "idfc-first-bank", name: "IDFC FIRST Bank", shortName: "IDFC FIRST", type: "Private bank", products: ["personal-loan", "home-loan", "business-loan", "loan-against-property", "car-loan", "used-car-loan", "gold-loan", "professional-loan"], strengths: ["Competitive personal loan rates", "Flexible business loan programmes", "Digital-first processing"], summary: "A newer private bank with a strong retail lending focus and digital onboarding.", bestFor: "Salaried personal loan borrowers and small businesses.", profile: ["IDFC FIRST is one of the more genuinely digital lenders on the panel, and it shows most on unsecured personal loans for salaried applicants, where a well-documented file can move quickly without a branch visit. For a borrower who wants speed and has nothing unusual in their profile, it is a strong first look.", "The business lending programmes are more flexible than a traditional bank's, which makes the bank useful for a small firm that is real and profitable but does not present the polished accounts a public sector lender expects. That flexibility is priced in, so it is a trade rather than a free advantage."], watchOuts: ["Flexibility on business files is reflected in pricing; a firm with clean audited accounts will usually do better at a larger bank.", "As a newer franchise, the branch network is thinner than at an established bank if you prefer to be served in person."], faqs: [{ question: "How fast is a personal loan here?", answer: "For a salaried applicant with documents ready, it is among the quicker routes on our panel. Speed still depends on your profile being straightforward, and we tell you if it is not." }, { question: "Will it lend to my small business?", answer: "Its programmes are more accommodating than a traditional bank's, which helps a profitable firm without polished accounts. Expect that flexibility to be priced in." }, { question: "Do I have to visit a branch?", answer: "Usually not for an unsecured retail loan. Secured lending still involves property and legal steps that cannot be done entirely online." }], website: "https://www.idfcfirstbank.com", updatedAt: "2026-09-01" },
  { slug: "yes-bank", name: "YES Bank", shortName: "YES Bank", type: "Private bank", products: ["personal-loan", "home-loan", "business-loan", "loan-against-property", "car-loan", "working-capital-loan"], strengths: ["Loan against property programmes", "Business banking focus", "Competitive personal loan offers"], summary: "A private bank with a growing retail and SME lending book.", bestFor: "SMEs and self-employed borrowers with property.", profile: ["YES Bank is most relevant to self-employed borrowers and smaller businesses with property to offer. A loan against property here can support a larger amount than an unsecured route, and the assessment takes the asset seriously rather than resting entirely on declared income.", "The retail and SME book has been rebuilding, which in practice means appetite can be selective and varies by segment. We treat it as a comparison point rather than an automatic first choice, and we check current appetite before we submit a file."], watchOuts: ["Appetite is more selective than at a larger private bank, so a file that fits one month may not the next.", "Pledging property puts the asset at risk; the lower rate against an unsecured loan reflects that, it is not a free saving."], faqs: [{ question: "Is this a good option for a self-employed borrower?", answer: "With property to offer, it is worth comparing. Without it, a specialist NBFC is usually the better route for informal income and we will direct you there." }, { question: "How much can I borrow against my property?", answer: "It depends on the valuation and on your ability to service the loan. We give you a realistic range before applying, not an optimistic one." }, { question: "Why check appetite before applying?", answer: "Lender appetite shifts by segment and by month. Submitting into a segment that is currently closed costs you a bureau enquiry for nothing, so we confirm first." }], website: "https://www.yesbank.in", updatedAt: "2026-09-01" },
  { slug: "indusind-bank", name: "IndusInd Bank", shortName: "IndusInd", type: "Private bank", products: ["personal-loan", "home-loan", "business-loan", "loan-against-property", "car-loan", "used-car-loan"], strengths: ["Strong vehicle finance franchise", "Personal loans for salaried professionals", "Loan against property"], summary: "A private bank with a notable vehicle finance business and active retail lending.", bestFor: "Car buyers and salaried personal loan applicants.", profile: ["IndusInd is a vehicle finance house with a bank attached, and that heritage is the reason to consider it. For a new or used car, the underwriting understands the asset properly, which tends to help borrowers whose profile is otherwise ordinary. If a car is what you are financing, this belongs on the shortlist.", "Its personal loans for salaried professionals are a reasonable comparison point, and loan against property is available for borrowers with an asset to pledge. Neither is the standout; the vehicle franchise is."], watchOuts: ["Outside vehicle finance the proposition is competitive rather than distinctive, so compare before assuming it wins.", "Used-vehicle lending depends heavily on the age and valuation of the car, which can change the amount available late in the process."], faqs: [{ question: "Why does the vehicle finance heritage matter?", answer: "Underwriting that understands the asset can be more accommodating on the borrower, particularly for used cars where the valuation carries part of the risk. It often produces a better outcome than a general-purpose lender." }, { question: "Can I finance a used car here?", answer: "Yes, and it is one of the stronger routes on the panel. The amount depends on the age and valuation of the vehicle, so we set expectations before you commit to a purchase." }, { question: "Is the personal loan competitive?", answer: "It is a fair comparison point for salaried applicants rather than an obvious winner. We quote it alongside the rest of the panel." }], website: "https://www.indusind.com", updatedAt: "2026-09-01" },
  { slug: "federal-bank", name: "Federal Bank", shortName: "Federal Bank", type: "Private bank", products: ["personal-loan", "home-loan", "gold-loan", "business-loan", "loan-against-property", "car-loan"], strengths: ["Strong NRI programmes", "Gold loans", "Presence across Kerala and South India"], summary: "A Kerala-headquartered private bank known for NRI banking, gold loans and home loans in South India.", bestFor: "NRI borrowers and South Indian home buyers.", profile: ["Federal Bank is the lender we reach for first on NRI files. The programmes are long-established, the documentation requirements for overseas income are understood rather than improvised, and that removes most of the friction that makes NRI lending painful elsewhere.", "Its gold loan and home loan business across Kerala and South India is the other reason to consider it. For a borrower in that region, the combination of local presence and NRI expertise is genuinely differentiated rather than a marketing claim."], watchOuts: ["The regional strength is real, and so is its limit: presence thins considerably outside South India.", "NRI lending still needs proper overseas income documentation; the process is smoother here, not lighter."], faqs: [{ question: "Why is this the usual choice for NRI borrowers?", answer: "The programmes are established and the teams handle overseas income documentation routinely rather than as an exception. That removes most of the friction NRI applicants meet at other lenders." }, { question: "Do I need to be in Kerala or South India?", answer: "For an NRI file, no. For a branch-served home or gold loan, regional presence matters and we factor it into the recommendation." }, { question: "Are gold loans worth considering here?", answer: "For a bank gold loan, yes, particularly in South India. A specialist gold loan NBFC is usually faster, so the choice depends on whether you value rate or speed." }], website: "https://www.federalbank.co.in", updatedAt: "2026-09-01" },
  { slug: "bajaj-finance", name: "Bajaj Finance", shortName: "Bajaj Finance", type: "NBFC", products: ["personal-loan", "business-loan", "loan-against-property", "professional-loan", "gold-loan", "used-car-loan", "machinery-loan"], strengths: ["Fast digital personal and business loans", "Professional loan programmes for doctors and CAs", "Flexi loan variants"], summary: "India's largest consumer finance NBFC, with a wide range of unsecured and secured lending products.", bestFor: "Professionals and businesses seeking quick unsecured loans.", profile: ["Bajaj Finance is the fastest route on the panel for an unsecured personal or business loan, and speed is genuinely the product. For a salaried or self-employed borrower who needs funds quickly and has a clean bureau record, a decision can arrive in a fraction of the time a bank takes.", "Its professional loan programmes for doctors and chartered accountants are worth knowing about, because they assess a qualified practice differently from a generic self-employed file. Flexi variants, where you draw and repay within a limit, suit lumpy business cash flow better than a fixed instalment does."], watchOuts: ["NBFC pricing on unsecured loans is generally above bank pricing; you are paying for speed and for flexible assessment.", "A flexi facility is easy to keep drawing on, which quietly extends how long you stay in debt if you are not disciplined."], faqs: [{ question: "Why choose an NBFC over a bank?", answer: "Speed and a more accommodating view of income. If your profile fits a bank comfortably and you are not in a hurry, a bank is usually cheaper and we will say so." }, { question: "What is a flexi loan and should I take one?", answer: "It lets you draw and repay within a sanctioned limit rather than paying a fixed instalment. It suits genuinely lumpy cash flow. It works against you if you treat the limit as income." }, { question: "Are professional loans different from business loans?", answer: "Yes. A qualified practice is assessed on the qualification and the practice, not purely on filed accounts, which usually produces a better outcome for a doctor or chartered accountant." }], website: "https://www.bajajfinserv.in", updatedAt: "2026-09-01" },
  { slug: "tata-capital", name: "Tata Capital", shortName: "Tata Capital", type: "NBFC", products: ["personal-loan", "home-loan", "business-loan", "loan-against-property", "car-loan", "used-car-loan", "education-loan", "machinery-loan", "working-capital-loan"], strengths: ["Broad product range", "Flexible business and equipment finance", "Home loans through its housing finance arm"], summary: "A diversified NBFC from the Tata group offering retail, SME and equipment finance.", bestFor: "SMEs needing equipment and working capital finance.", profile: ["Tata Capital is the broadest NBFC on the panel, which makes it useful when a borrower needs more than one kind of facility at once. A growing firm buying equipment while also needing working capital can often be handled as a single relationship rather than assembled from three lenders.", "Equipment and machinery finance is the part we use most. Assessment gives proper weight to the asset being bought and to the contract behind it, which suits a manufacturer or contractor whose balance sheet alone would understate what they can service."], watchOuts: ["Breadth is not the same as being cheapest in any single category; compare the specific product rather than the group.", "Equipment finance ties the facility to the asset, so the funding is not freely usable for other purposes."], faqs: [{ question: "When is an equipment loan better than a business loan?", answer: "When the asset itself carries part of the risk. That usually means a larger amount and a longer tenure than an unsecured business loan would give you, at a lower rate." }, { question: "Can one lender cover machinery and working capital?", answer: "Here, often yes, which saves you assembling a facility from several lenders. Whether it is the cheapest combination is what we check for you." }, { question: "Is a Tata group NBFC cheaper than a bank?", answer: "Usually not on rate. The reason to use it is flexibility on assessment and the ability to structure around an asset, which a bank may not offer." }], website: "https://www.tatacapital.com", updatedAt: "2026-09-01" },
  { slug: "aditya-birla-capital", name: "Aditya Birla Capital", shortName: "ABC", type: "NBFC", products: ["personal-loan", "business-loan", "loan-against-property", "home-loan", "working-capital-loan"], strengths: ["Personal and business loans with digital processing", "Loan against property", "Housing finance arm"], summary: "A diversified financial services group with active retail and SME lending.", bestFor: "Self-employed borrowers and SMEs.", profile: ["Aditya Birla Capital is a dependable comparison point for self-employed borrowers and SMEs, particularly where a file needs a more considered look than a bank's programme lending allows. Personal and business loans are processed digitally, and loan against property is available where an asset is on the table.", "We place files here when the borrower sits between two stools: too irregular for a bank's standard programme, but strong enough that a high-cost lender would be overpaying. It is frequently the sensible middle option rather than the obvious winner."], watchOuts: ["Rarely the cheapest and rarely the fastest; its value is in taking a considered view of a middling file.", "The housing finance arm is separate from the NBFC, so a home loan and a business loan here are two relationships, not one."], faqs: [{ question: "Who is this lender actually right for?", answer: "A self-employed borrower or SME whose file is too irregular for a bank programme but too strong to justify high-cost lending. It is often the sensible middle option." }, { question: "Is the home loan part of the same company?", answer: "The housing finance business is a separate arm from the NBFC, so a home loan and a business loan are two relationships. We tell you which entity your file goes to." }, { question: "How quickly can it decide?", answer: "Faster than a bank, slower than the quickest digital NBFCs. If speed is the priority we will point you at a lender built for it." }], website: "https://www.adityabirlacapital.com", updatedAt: "2026-09-01" },
  { slug: "lt-finance", name: "L&T Finance", shortName: "L&T Finance", type: "NBFC", products: ["personal-loan", "business-loan", "loan-against-property", "home-loan", "used-car-loan"], strengths: ["Digital personal loans", "SME lending", "Rural and semi-urban reach"], summary: "A large NBFC with growing retail and SME lending and strong semi-urban presence.", bestFor: "Borrowers in tier 2 cities and beyond.", profile: ["L&T Finance matters most for borrowers outside the big metros. Its reach into tier two cities and semi-urban markets means a file that a metro-focused lender would deprioritise gets a proper look, and local presence makes the practical steps of a secured loan far easier.", "For a salaried or self-employed borrower in a smaller city needing a personal or business loan, this is often a stronger option than the national brands that technically cover the location but do not really serve it. In a metro, there are usually sharper choices."], watchOuts: ["In metros the proposition is ordinary; the advantage is geographic and disappears where competition is dense.", "NBFC pricing applies, so a borrower who would qualify comfortably at a bank should compare before committing."], faqs: [{ question: "Why does location change the recommendation?", answer: "Coverage on paper is not the same as service on the ground. A lender with real presence in your city handles valuation, verification and disbursal faster, which matters most on secured loans." }, { question: "Is it competitive in Mumbai or Delhi?", answer: "It is a fair comparison point rather than a standout. In dense markets we usually find sharper pricing elsewhere and will tell you where." }, { question: "Does it lend to small businesses?", answer: "Yes, and the semi-urban reach is the reason to consider it. A firm outside the metros often gets a more attentive assessment here." }], website: "https://www.ltfs.com", updatedAt: "2026-09-01" },
  { slug: "piramal-finance", name: "Piramal Finance", shortName: "Piramal", type: "NBFC", products: ["home-loan", "loan-against-property", "business-loan", "personal-loan", "used-car-loan"], strengths: ["Affordable housing loans", "Loan against property for self-employed", "Flexible income assessment"], summary: "An NBFC focused on affordable housing, loans against property and small business lending.", bestFor: "Self-employed borrowers with informal income and affordable home buyers.", profile: ["Piramal is one of the few lenders on the panel that will look properly at income which does not arrive as a salary slip. For a self-employed borrower with real earnings and informal records, the assessment methods here can produce an approval where a bank would decline without discussion.", "That capability shows up in affordable housing and in loans against property, which is where we use it most. It is not a lender of first resort for a clean salaried file, and we do not present it as one."], watchOuts: ["Flexible assessment is priced accordingly; expect to pay more than a bank would charge a documentable borrower.", "A loan against property puts your asset at risk, and that risk is the reason the rate is lower than an unsecured alternative."], faqs: [{ question: "What does informal income assessment actually mean?", answer: "The lender builds a view of your earnings from banking patterns, business evidence and local verification rather than only from filed returns. It is how a real business with imperfect paperwork gets funded." }, { question: "Will I pay more than at a bank?", answer: "Almost certainly, and that is the trade. If your income can be documented properly we will take you to a bank instead, because it will be cheaper." }, { question: "Is it suitable for an affordable home purchase?", answer: "Yes, that is one of its core markets, particularly where the buyer's income is informal. We compare it against the housing finance companies that serve the same segment." }], website: "https://www.piramalfinance.com", updatedAt: "2026-09-01" },
  { slug: "poonawalla-fincorp", name: "Poonawalla Fincorp", shortName: "Poonawalla", type: "NBFC", products: ["personal-loan", "business-loan", "professional-loan", "loan-against-property", "machinery-loan"], strengths: ["Professional loans for doctors and CAs", "Digital personal loans", "Business loans for MSMEs"], summary: "An NBFC focused on professional, personal and small business loans with digital onboarding.", bestFor: "Doctors, CAs and small businesses.", profile: ["Poonawalla Fincorp is built around professionals and small businesses, and the professional loan programmes for doctors and chartered accountants are the reason to look here. A qualified practice is assessed on the qualification and the practice itself, which usually beats being treated as a generic self-employed applicant.", "Digital processing keeps the timeline short for a clean file. For an MSME needing an unsecured business loan quickly, it is a reasonable alternative to the larger consumer finance NBFCs, and worth quoting alongside them."], watchOuts: ["The advantage is concentrated in professional and small business lending; elsewhere it is one option among several.", "Unsecured NBFC pricing applies, so a borrower who fits a bank programme should compare first."], faqs: [{ question: "What counts as a professional loan?", answer: "Lending to a qualified practitioner such as a doctor or chartered accountant, assessed on the qualification and the practice rather than purely on filed accounts. It usually produces a better outcome than a generic self-employed file." }, { question: "How does it compare with the largest consumer NBFCs?", answer: "It is genuinely competitive for professionals and small businesses. We quote it alongside them rather than assuming the bigger name wins." }, { question: "How fast is a decision?", answer: "Short for a clean, well-documented file. Anything unusual in the profile slows it down, and we flag that before applying." }], website: "https://poonawallafincorp.com", updatedAt: "2026-09-01" },
  { slug: "hero-fincorp", name: "Hero FinCorp", shortName: "Hero FinCorp", type: "NBFC", products: ["personal-loan", "business-loan", "loan-against-property", "used-car-loan", "machinery-loan"], strengths: ["Personal and business loans", "Loan against property", "Used vehicle finance"], summary: "An NBFC from the Hero group offering retail and SME loans.", bestFor: "Small businesses and used vehicle buyers.", profile: ["Hero FinCorp is a practical option for small businesses and used vehicle buyers, particularly where the borrower is real and serviceable but would not clear a bank's programme cleanly. Loan against property is available where an asset can support a larger amount.", "We treat it as a comparison point rather than a first choice. It earns its place when the alternatives have declined a workable file, and it is often more accommodating than its size would suggest."], watchOuts: ["Pricing reflects the flexibility; a borrower who fits a bank should go to the bank.", "Used vehicle amounts depend on the age and valuation of the asset, which can move late in the process."], faqs: [{ question: "When would you recommend this lender?", answer: "When a workable file has been declined elsewhere on technicalities, or when a used vehicle or small business loan needs a more accommodating view than a bank offers." }, { question: "Can I borrow against my property here?", answer: "Yes, and it usually supports a larger amount than an unsecured loan. The asset is at risk, which is what makes the rate lower." }, { question: "Is it competitive on rate?", answer: "Not against a bank. Its value is in saying yes to files a bank declines, and we are straightforward about that trade." }], website: "https://www.herofincorp.com", updatedAt: "2026-09-01" },
  { slug: "lic-housing-finance", name: "LIC Housing Finance", shortName: "LIC HFL", type: "Housing finance company", products: ["home-loan", "loan-against-property", "home-loan-balance-transfer"], strengths: ["Competitive home loan rates", "Long tenures", "Nationwide presence"], summary: "One of India's largest housing finance companies with a long track record in home loans.", bestFor: "Home buyers seeking HFC flexibility with competitive rates.", profile: ["LIC Housing Finance is a long-established housing lender with a nationwide footprint and a track record measured in decades rather than funding rounds. For a home buyer who wants housing finance company flexibility without moving to a smaller or newer institution, it is the steady choice.", "Long tenures and a willingness to look at a range of property types make it useful where a bank has hesitated over the building's age or the borrower's income structure. It is not the fastest lender on the panel, and we plan timelines accordingly."], watchOuts: ["Processing is thorough rather than quick, so allow time if you have a booking deadline.", "A longer tenure lowers the instalment and raises the total interest you pay; the cheaper monthly figure is not a cheaper loan."], faqs: [{ question: "Why choose a housing finance company over a bank?", answer: "Greater flexibility on property type and on income that is not a straightforward salary. Banks usually price better for a clean file, so the choice depends on which part of your file is awkward." }, { question: "Should I take the longest tenure offered?", answer: "Only if you need the lower instalment. A longer tenure increases total interest substantially, and we show you both numbers before you decide." }, { question: "Will it lend on an older building?", answer: "It is generally more accommodating than a bank on property age and type, though every case turns on the legal and technical review. We check before you commit." }], website: "https://www.lichousing.com", updatedAt: "2026-09-01" },
  { slug: "pnb-housing-finance", name: "PNB Housing Finance", shortName: "PNB Housing", type: "Housing finance company", products: ["home-loan", "loan-against-property", "home-loan-balance-transfer"], strengths: ["Home loans for self-employed", "Loan against property", "Affordable housing focus"], summary: "A large housing finance company with home loan and LAP programmes across income segments.", bestFor: "Self-employed home buyers and property owners.", profile: ["PNB Housing Finance works across income segments, which makes it useful for self-employed home buyers whose file does not fit a bank's salaried template. Assessment can accommodate business income and less conventional documentation, and loans against property are part of the same franchise.", "The affordable housing focus means it serves buyers a large bank would not prioritise. For a first-time buyer with a modest ticket size and imperfect paperwork, it is frequently a better route than pushing a bank application that is likely to fail."], watchOuts: ["Housing finance company pricing generally sits above bank pricing for a comparable, documentable borrower.", "Flexibility applies to the income assessment, not to the legal and technical review, which remains strict."], faqs: [{ question: "Is this suitable for a self-employed buyer?", answer: "Yes, that is one of its core segments. Business income and less conventional documentation are handled routinely rather than as an exception." }, { question: "What does affordable housing focus mean for me?", answer: "It means smaller ticket sizes and first-time buyers are served properly rather than deprioritised. If a large bank has been slow with your file, this is worth comparing." }, { question: "Will my property still be scrutinised?", answer: "Yes. Flexibility here applies to how your income is assessed, not to the title and construction review, which stays strict for good reason." }], website: "https://www.pnbhousing.com", updatedAt: "2026-09-01" },
  { slug: "bajaj-housing-finance", name: "Bajaj Housing Finance", shortName: "Bajaj Housing", type: "Housing finance company", products: ["home-loan", "loan-against-property", "home-loan-balance-transfer"], strengths: ["Competitive home loan rates", "Fast processing", "Balance transfer with top-up"], summary: "A fast-growing housing finance company known for competitive pricing and quick turnaround.", bestFor: "Home loan balance transfers and salaried home buyers.", profile: ["Bajaj Housing Finance is where we look first for a balance transfer. Pricing is competitive, processing is quick by housing finance standards, and the ability to add a top-up to the transferred loan means a borrower can lower their rate and raise funds in one move rather than two.", "For a salaried buyer with a clean profile and a standard property, it is also a serious primary lender rather than only a refinancing option. The speed is real and is the main reason to prefer it over a slower established name."], watchOuts: ["A balance transfer only pays once the rate gap covers the switching costs; the arithmetic decides, not the headline rate.", "A top-up raises your total debt at a longer tenure, so it is cheap money that you repay for a long time."], faqs: [{ question: "When is a balance transfer actually worth it?", answer: "When the saving over your remaining tenure clearly exceeds the processing, legal and technical costs of moving. We run that calculation for you and will tell you when the answer is no." }, { question: "Should I add a top-up while transferring?", answer: "Only for something that justifies a long repayment. A top-up is cheap compared with unsecured borrowing, but you pay it back over the remaining home loan tenure." }, { question: "Is it a good lender for a first purchase?", answer: "Yes for a salaried buyer with a clean profile and a standard property, where the quick processing is a genuine advantage." }], website: "https://www.bajajhousingfinance.in", updatedAt: "2026-09-01" },
  { slug: "aavas-financiers", name: "Aavas Financiers", shortName: "Aavas", type: "Housing finance company", products: ["home-loan", "loan-against-property"], strengths: ["Affordable housing loans", "Informal income assessment", "Tier 2 and 3 presence"], summary: "An affordable housing finance company serving self-employed and informal-income borrowers in smaller cities.", bestFor: "Affordable home buyers with informal income.", profile: ["Aavas lends where most of the market does not look. Its business is affordable housing for self-employed and informal-income borrowers in tier two and tier three cities, and the assessment is built for exactly that: local verification and a considered view of real earnings rather than a demand for filed returns.", "If you run a small business in a smaller city and have been turned away by banks for lack of paperwork, this is one of the few genuine routes to a home loan. We are candid that it costs more, because the alternative is usually no loan at all."], watchOuts: ["Pricing is materially above bank pricing; this is specialist lending to an underserved segment, not a bargain.", "Ticket sizes are aimed at affordable housing, so a large purchase is a poor fit here."], faqs: [{ question: "Will it lend without income tax returns?", answer: "Its assessment is built around informal income, using banking patterns and local verification. Requirements still apply, but the absence of conventional returns is not automatically a refusal." }, { question: "Why is the rate higher than a bank's?", answer: "Because the lending is more labour-intensive and the segment carries more risk. If your income can be documented conventionally, we will take you to a cheaper lender instead." }, { question: "Is there a limit on how much I can borrow?", answer: "Practically yes, because the focus is affordable housing. For a larger purchase we would point you at a different lender." }], website: "https://www.aavas.in", updatedAt: "2026-09-01" },
  { slug: "au-small-finance-bank", name: "AU Small Finance Bank", shortName: "AU SFB", type: "Small finance bank", products: ["home-loan", "loan-against-property", "business-loan", "car-loan", "used-car-loan", "personal-loan", "gold-loan"], strengths: ["Vehicle finance heritage", "Secured business loans", "Strong presence in Rajasthan and western India"], summary: "A small finance bank with roots in vehicle finance and a growing secured lending franchise.", bestFor: "Vehicle buyers and small businesses in North and West India.", profile: ["AU Small Finance Bank grew out of vehicle finance, and that origin still shapes it. Underwriting understands assets, which makes it a strong option for vehicle purchases and for secured business lending where the security is doing real work in the assessment.", "Its presence across Rajasthan and western India is deeper than the national names, so a borrower there often gets a more attentive file. As a bank rather than an NBFC it can price better than a comparable finance company, which makes it a useful middle option."], watchOuts: ["Regional depth is a real advantage and a real limit; coverage elsewhere is thinner.", "The strength is in secured lending, so an unsecured file may be better placed with a lender built for it."], faqs: [{ question: "Is it a bank or a finance company?", answer: "A small finance bank, which usually means better pricing than a comparable NBFC with more flexibility than a large bank. It often sits usefully between the two." }, { question: "Why is it good for vehicle loans?", answer: "The business grew out of vehicle finance, so the underwriting understands the asset. That tends to help a borrower whose profile is otherwise ordinary." }, { question: "Does location matter?", answer: "Yes. Presence is deepest across Rajasthan and western India, where files get more attention. Elsewhere we usually compare it against stronger local options." }], website: "https://www.aubank.in", updatedAt: "2026-09-01" },
  { slug: "muthoot-finance", name: "Muthoot Finance", shortName: "Muthoot", type: "NBFC", products: ["gold-loan"], strengths: ["India's largest gold loan NBFC", "Same-day disbursal", "Wide branch network"], summary: "The country's largest gold loan company with thousands of branches and quick disbursal.", bestFor: "Gold loan borrowers seeking speed and flexible schemes.", profile: ["Muthoot is the fastest way to raise money against gold you already own. Because the loan is secured by the metal itself, your credit score is largely beside the point, and disbursal on the same day is normal rather than exceptional. For a genuine short-term need, that combination is hard to beat.", "The branch network means there is usually one nearby, which matters when you are physically carrying the security. We recommend gold loans for short, defined needs, and we say plainly when a cheaper long-term option would serve you better."], watchOuts: ["Your gold is genuinely at risk. If the price falls or you fall behind, the lender can require a top-up or sell the pledged items.", "Short tenures mean repayment comes round quickly; a gold loan is a poor way to fund a long-term need."], faqs: [{ question: "Does my credit score matter for a gold loan?", answer: "Far less than for any other loan, because the gold secures it. That is what makes this a workable option for borrowers a bank has already declined." }, { question: "How quickly can I get the money?", answer: "Same-day disbursal is routine once your gold is valued at the branch. It is the fastest option on our panel for that reason." }, { question: "What happens if I cannot repay?", answer: "The lender can require you to add security or can sell the pledged gold to recover the amount. Take a gold loan only for a short, defined need where you know the repayment is coming." }], website: "https://www.muthootfinance.com", updatedAt: "2026-09-01" },
  { slug: "manappuram-finance", name: "Manappuram Finance", shortName: "Manappuram", type: "NBFC", products: ["gold-loan", "used-car-loan"], strengths: ["Gold loans with online top-up", "Flexible schemes", "Presence across South and West India"], summary: "A leading gold loan NBFC with digital gold loan services.", bestFor: "Gold loan borrowers wanting online management.", profile: ["Manappuram covers the same ground as the larger gold loan houses with more emphasis on managing the loan online. Being able to top up, pay interest or track a pledge without visiting a branch is a real convenience for a borrower who rolls a gold loan more than once.", "Presence is strongest across South and West India. For a short-term need against gold you already hold, it is a fair comparison against the largest specialist, and worth quoting alongside it."], watchOuts: ["The pledged gold is at risk if the price falls or repayment slips, exactly as with any gold loan.", "Online convenience makes rolling a loan easy, which can quietly turn a short-term borrowing into a long-term one."], faqs: [{ question: "What can I actually do online?", answer: "Interest payment, top-up and tracking are handled digitally, which saves branch visits if you hold the loan for more than a few weeks. The gold still has to be pledged in person." }, { question: "How does it compare with the largest gold loan NBFC?", answer: "The core product is similar and the choice usually comes down to branch access and the scheme on offer. We quote both rather than assuming the larger name wins." }, { question: "Is a gold loan safe?", answer: "It is secured on your gold, so the risk is yours rather than the lender's. Use it for a short, defined need and have the repayment planned before you pledge." }], website: "https://www.manappuram.com", updatedAt: "2026-09-01" },
];

export const lenderMap = new Map(lenders.map((l) => [l.slug, l]));
export const getLender = (slug: string) => lenderMap.get(slug);
export const lendersForProduct = (productSlug: string) => lenders.filter((l) => l.products.includes(productSlug));
export const lenderTypes: LenderType[] = ["Public sector bank", "Private bank", "Housing finance company", "NBFC", "Small finance bank"];
